     -1 -3   0;
     -4 -13  -1];

disp('Matrix T:');
disp(T);

% Calculate eigenvalues and eigenvectors
% V = matrix of eigenvectors (each column is one eigenvector)
% D = diagonal matrix of eigenvalues
[V, D] = eig(T);

disp('Eigenvalues (diagonal of D):');
disp(D);

disp('Eigenvectors (columns of V):');
disp(V);

% Display eigenvalues clearly
eigenvalues = diag(D);          % extract diagonal elements
disp('Eigenvalue list:');
for i = 1:length(eigenvalues)
  fprintf('lambda_%d = %.4f\n', i, eigenvalues(i));
end

% Verify: T*v = lambda*v for first eigenvector
disp('Verification T*v1 vs lambda1*v1:');
disp(T * V(:,1));               % T times first eigenvector
disp(D(1,1) * V(:,1));          % lambda1 times first eigenvector

