% Q6(a) - Line specifiers and figure command demo

x = 0:0.1:2*pi;       % x values from 0 to 2*pi
y1 = sin(x);          % first function
y2 = cos(x);          % second function

% Using line specifiers to distinguish curves
figure(1);            % open figure window 1
plot(x, y1, 'r-o');   % red solid line with circle markers
hold on;              % keep current plot
plot(x, y2, 'b--*');  % blue dashed line with asterisk markers
legend('sin(x)', 'cos(x)');
xlabel('x');
ylabel('y');
title('Sine and Cosine with Line Specifiers');
grid on;

% Using figure to open a separate window
figure(2);            % open NEW separate figure window
plot(x, y1.^2, 'g:s'); % green dotted with square markers
title('sin^2(x) in separate figure');

% Q6(b) - Plot f(x) and g(x) on same figure

x = -2:0.01:4;              % x range from -2 to 4

% Define functions using element-wise operations
f = x.^3 - 2.*x.^2 - 10.*sin(x).^2 - exp(0.9.*x);
g = -3.*x.^4 + 10.*x.^2 - 3;

% Plot both functions
figure;
plot(x, f, 'b-', 'LineWidth', 1.5);    % plot f(x) in blue
hold on;                                 % keep current axes
plot(x, g, 'r--', 'LineWidth', 1.5);   % plot g(x) in red dashed

% Add labels, legend, title, grid
xlabel('x');
ylabel('f(x) and g(x)');
title('Plot of f(x) and g(x) for -2 \leq x \leq 4');
legend('f(x) = x^3 - 2x^2 - 10sin^2(x) - e^{0.9x}', ...
       'g(x) = -3x^4 + 10x^2 - 3');
