% Add more lines using line() command (no hold on needed)
line(x, cos(x), 'Color', 'r', 'LineStyle', '--', 'LineWidth', 1.5);
line(x, 0.5*sin(2*x), 'Color', 'g', 'LineStyle', ':', 'LineWidth', 1.5);

% Add labels and legend
xlabel('x (radians)');
ylabel('Amplitude');
title('Multiple Graphs using line() Command');
legend('sin(x)', 'cos(x)', '0.5*sin(2x)');
grid on;

% Q6(d) - 3D surface plot and projections of z = r*theta

% Create grid of r and theta values
r = linspace(0, 2, 50);                   % r from 0 to 2
theta = linspace(0, 2*pi, 50);            % theta from 0 to 360 deg (in radians)
[R, T] = meshgrid(r, theta);              % create 2D grid

% Convert to Cartesian coordinates
X = R .* cos(T);                          % x = r*cos(theta)
Y = R .* sin(T);                          % y = r*sin(theta)
Z = R .* T;                               % z = r*theta

% i) 3D Surface Plot
figure(1);
surf(X, Y, Z);                            % plot 3D surface
shading interp;                           % smooth shading
colorbar;
xlabel('X'); ylabel('Y'); zlabel('Z');
title('3D Surface: z = r*\theta');

% ii) Projections
% XY plane projection (top view — looking down Z axis)
figure(2);
surf(X, Y, Z);
view(0, 90);                              % azimuth=0, elevation=90
title('Projection on XY plane');
xlabel('X'); ylabel('Y');

% XZ plane projection (front view — looking along Y axis)
figure(3);
surf(X, Y, Z);
view(0, 0);                               % azimuth=0, elevation=0
title('Projection on XZ plane');
xlabel('X'); zlabel('Z');

% YZ plane projection (side view — looking along X axis)
figure(4);
surf(X, Y, Z);
view(90, 0);                              % azimuth=90, elevation=0
title('Projection on YZ plane');
ylabel('Y'); zlabel('Z');

% Q7(a) - Difference between roots() and poly()

% Define polynomial: x^3 - 6x^2 + 11x - 6
p = [1, -6, 11, -6];    % coefficient vector

% roots(): find roots from coefficients
r = roots(p);
disp('Roots of polynomial:');
disp(r);

% poly(): find coefficients from roots
p2 = poly(r);           % reconstruct polynomial from roots
disp('Polynomial coefficients from roots:');
disp(p2);               % should match original p

% Verification
