disp(p2);

% Q7(b) - Specific heat of dry air polynomial

% Polynomial coefficients
% cp = 0.99403 + 1.671e-4*T + 9.7215e-8*T^2 - 9.5838e-11*T^3

% i) Calculate cp for T = 0 to 1200 K
T = 0:1:1200;                    % temperature range
cp = 0.99403 + 1.671e-4.*T + 9.7215e-8.*T.^2 - 9.5838e-11.*T.^3;

disp('cp values (first 5):');
disp(cp(1:5));

% Plot cp vs T
figure;
plot(T, cp, 'b-', 'LineWidth', 1.5);
xlabel('Temperature T (K)');
ylabel('cp [kJ/(kg.K)]');
title('Specific Heat of Dry Air vs Temperature');
grid on;

% ii) Find T when cp = 1.1 kJ/(kg K)
% Rearrange: -9.5838e-11*T^3 + 9.7215e-8*T^2 + 1.671e-4*T + (0.99403-1.1) = 0
coeffs = [-9.5838e-11, 9.7215e-8, 1.671e-4, (0.99403 - 1.1)];

T_roots = roots(coeffs);         % find all roots
disp('All roots (T values):');
disp(T_roots);

% Find physically meaningful root (real, between 0 and 1200 K)
T_real = T_roots(imag(T_roots) == 0 & real(T_roots) >= 0 & real(T_roots) <= 1200);
fprintf('Temperature for cp = 1.1 kJ/(kg.K): T = %.2f K\n', T_real);

% Q7(d) - Interpolation (extrapolation) using interp1

% Given data points
x = [20, 29];           % known x values
y = [100, 121];         % known y values

% Find y at x = 36 using linear interpolation/extrapolation
x_query = 36;
y_interp = interp1(x, y, x_query, 'linear', 'extrap');

fprintf('y at x = %d is: %.4f\n', x_query, y_interp);

% Manual verification
m = (y(2) - y(1)) / (x(2) - x(1));     % slope
y_manual = y(1) + m * (x_query - x(1)); % linear formula
fprintf('Manual calculation: y = %.4f\n', y_manual);

% Q7(e) - Curve fitting for mu = C*T^(3/2) / (T+S)
% (Sutherland's Law for viscosity)

% Given data — convert Celsius to Kelvin
T_C = [-20, 0, 40, 100, 200, 300, 400];  % Celsius
T = T_C + 273.15;                          % convert to Kelvin
mu = [1.63, 1.71, 1.87, 2.17, 2.53, 2.98, 3.32];

% ---- Linearization Method ----
% mu*(T+S) = C*T^(3/2)
% mu/sqrt(T) = C - S * mu/T^(3/2)
% Let Y = mu./sqrt(T), X = mu./(T.^(3/2))
% Y = C - S*X  => linear: Y = -S*X + C

Y = mu ./ sqrt(T);              % transformed Y
X = mu ./ (T .^ (3/2));        % transformed X

% Linear fit: Y = p(1)*X + p(2)
p = polyfit(X, Y, 1);           % p(1) = -S, p(2) = C
S = -p(1);                      % extract S
C = p(2);                       % extract C
fprintf('C = %.6f\n', C);
fprintf('S = %.4f\n', S);

% Verify fit
mu_fit = C .* T.^(3/2) ./ (T + S);

% Plot
figure;
plot(T, mu, 'ro', 'MarkerSize', 8);
hold on;
plot(T, mu_fit, 'b-', 'LineWidth', 1.5);
xlabel('Temperature T (K)');
ylabel('\mu (viscosity)');
legend('Experimental', 'Fitted Curve');
title('Sutherland Law Curve Fitting');
grid on;

% Q8(d) - Calculate e^15 using Taylor series (20 terms)

x = 15;             % value of x
n_terms = 20;       % number of terms (n = 0 to 19)
e_sum = 0;          % initialize sum to zero

for n = 0:(n_terms - 1)
  term = x^n / factorial(n);    % compute x^n / n!
  e_sum = e_sum + term;         % add term to running sum
end

fprintf('e^15 using 20 terms of series: %.6f\n', e_sum);
fprintf('Exact value (exp function):     %.6f\n', exp(15));
fprintf('Error: %.6f\n', abs(exp(15) - e_sum));
